F = np.load(WORK/'base_feats.npz'); y=F['y']; P=practice()
def LNr(X): X=X-X.mean(1,keepdims=True); return X/X.std(1,keepdims=True)
def zsall(X): mu=X.mean(0); sd=X.std(0)+1e-6; return (X-mu)/sd/np.sqrt(X.shape[1])
def loo_pred(Z,y,g,l):
    sq=(Z**2).sum(1); D2=np.maximum(sq[:,None]+sq[None]-2*Z@Z.T,0); T=np.eye(8)[y]-1/8
    K=np.exp(-g*D2); w,V=np.linalg.eigh(K); f=w/(w+l); Hd=((V**2)*f[None]).sum(1); Yh=V@(f[:,None]*(V.T@T))
    return (Yh-Hd[:,None]*T)/(1-Hd[:,None])
